INSERT INTO cars (id, name, serial, brand, series, manufacture, year, vehicle_type, colour, scale, description, images, featured, featured_image, gifter, source, is_treasure_hunt, model, variant_id, variant_label, ownership, is_incoming, is_wishlist, set_name, set_number, created_at) VALUES (1, 'BMW M1', 'CW-064', 'Hot Wheels', 'Silver Series', 'BMW', '2024', 'Car', 'Orange', '1/64', 'The BMW M1 is BMWs first true supercar and the car that gave birth to the legendary M division. Built in the late 1970s, it pairs a striking wedge-shaped design with a high-revving inline-six, blending motorsport pedigree with timeless styling, an icon that still defines BMW performance heritage today.', '["/images/cars/bmw-m1-1.webp"]', 1, NULL, 'Alex', 'Local toy store', 0, NULL, NULL, NULL, NULL, 0, 0, 'BMW', '1/5', '2026-06-22 05:48:49');
