INSERT INTO cars (id, name, serial, brand, series, manufacture, year, vehicle_type, colour, scale, description, images, featured, featured_image, gifter, source, is_treasure_hunt, model, variant_id, variant_label, ownership, is_incoming, is_wishlist, set_name, set_number, created_at) VALUES (3, '84 Audi Sport Quattro', 'CW-279', 'Hot Wheels', 'Mainline', 'Audi', NULL, 'Car', 'Red', '1/64', 'The 1984 Audi Sport Quattro rewrote rally history with its turbocharged 5-cylinder engine and revolutionary quattro all-wheel-drive. This Hot Wheels Mainline casting immortalises the boxy, aggressive homologation special in striking red.', '["/images/cars/84-audi-sport-quattro-1.webp"]', 0, NULL, 'Alex', 'Gift', 0, 'Audi 90 Quattro', 'hw-audi-quatro-red', NULL, NULL, 0, 0, NULL, NULL, '2026-07-12 13:22:52');
