INSERT INTO cars (id, name, serial, brand, series, manufacture, year, vehicle_type, colour, scale, description, images, featured, featured_image, gifter, source, is_treasure_hunt, model, variant_id, variant_label, ownership, is_incoming, is_wishlist, set_name, set_number, created_at) VALUES (15, 'BMW M3 TOURING', 'CW-304', 'Majorette', 'Mainline', 'BMW', '2026', 'Car', 'blue', '1/64', 'The BMW M3 Touring blends supercar-level performance with the practicality of a high-performance estate, powered by a twin-turbo inline-six engine and BMW''s xDrive all-wheel-drive system. With its aggressive M styling, spacious cargo area, and track-ready dynamics, it offers an ideal balance of everyday usability and exhilarating driving.', '["/images/cars/bmw-m3-touring-1.webp"]', 0, NULL, NULL, 'Online', 0, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, '2026-08-05 04:21:08');
