INSERT INTO car_info (car_id, status, data) VALUES (1, 'confirmed', '{"casting": {"source": "Hot Wheels Wiki", "title": "BMW M1", "url": "https://hotwheels.fandom.com/wiki/BMW_M1", "fields": {"Debut series": "Real Riders", "Produced": "1983 - 1996 (original) / 2012 - present (retool)", "Designer": "Larry Wood", "Number": "4364"}}, "version": {"year": "2025", "series": "BMW / 1/5", "color": "Inka Orange", "tampo": "Detailed headlights, taillights and trim", "wheel": "S5", "toy": "JBY59", "notes": "Base code(s): U07I, U13I, U25I", "image": "https://static.wikia.nocookie.net/hotwheels/images/f/f0/JBY59.jpg/revision/latest/scale-to-width-down/300?cb=20260127095614"}, "realCar": {"title": "BMW M1", "url": "https://en.wikipedia.org/wiki/BMW_M1", "description": "Sports car manufactured by BMW from 1978 to 1981", "summary": "The BMW M1 (model code E26) is a mid-engined sports car produced by German automotive manufacturer BMW from 1978 until 1981. In the late 1970s, Italian automobile manufacturer Lamborghini entered into an agreement with BMW to build a production racing car in sufficient quantity for homologation, but conflicts arose that prompted BMW to produce the car themselves. The resulting car was sold to the public, from 1978 until 1981, as the BMW M1. It was the first mid-engine BMW automobile to be mass-produced; the second was the i8 plug-in hybrid sports car."}}');
INSERT INTO car_info (car_id, status, data) VALUES (2, 'confirmed', '{"casting": {"source": "Hot Wheels Wiki", "title": "Sweet Driver", "url": "https://hotwheels.fandom.com/wiki/Sweet_Driver", "fields": {"Debut series": "Fast Foodie", "Produced": "2022 – Present", "Designer": "Ryu Asada", "Number": "HCT40"}}, "version": {"year": "2026", "series": "Sweet Rides / 4/5", "color": "White", "tampo": "White, red & pink swirl frosting, TH Flame logo at front center, Hot Wheels logo at left", "wheel": "Pink tire, chrome red AeroDisc", "toy": "JJM09", "notes": "Treasure Hunt / Base code(s): V11N, V12N, V13N", "image": "https://static.wikia.nocookie.net/hotwheels/images/5/5f/CupcakeRacer.jpg/revision/latest/scale-to-width-down/300?cb=20260513083806"}, "realCar": null}');
INSERT INTO car_info (car_id, status, data) VALUES (3, 'confirmed', '{"casting": {"source": "Hot Wheels Wiki", "title": "''84 Audi Sport quattro", "url": "https://hotwheels.fandom.com/wiki/''84_Audi_Sport_quattro", "fields": {"Debut series": "Baja Blazers", "Produced": "2019 – Present", "Designer": "Dmitriy Shakhmatov", "Number": "FWG04"}}, "version": {"year": "2025", "series": "Wild Widebody / 5/5", "color": "Metalflake silver", "tampo": "Detailed headlights, black and orange diagonals, Castrol, Audi, quattro wordmarks on side, \"AA\" on front fender, Treasure Hunt flame logo on rear fender", "wheel": "White lip, Black AeroDisc", "toy": "JBC33", "notes": "Treasure Hunt / Base code(s): U26N, U27N, U28N,", "image": "https://static.wikia.nocookie.net/hotwheels/images/6/63/1984quattro.jpg/revision/latest/scale-to-width-down/300?cb=20250930223658"}, "realCar": {"title": "Audi Quattro", "url": "https://en.wikipedia.org/wiki/Audi_Quattro", "description": "Car model", "summary": "The Audi Quattro is a road and rally car, produced by the German automobile manufacturer Audi, part of the Volkswagen Group. It was first shown at the 1980 Geneva Motor Show on 3 March. Production continued until 1991."}}');
INSERT INTO car_info (car_id, status, data) VALUES (4, 'confirmed', '{"casting": {"source": "Hot Wheels Wiki", "title": "1966 Triumph Tiger 100", "url": "https://hotwheels.fandom.com/wiki/1966_Triumph_Tiger_100", "fields": {"Debut series": "Factory Fresh", "Produced": "2024 – Present", "Designer": "Eric Han", "Number": "HRY62"}}, "version": {"year": "2025", "series": "HW Moto / 5/5", "color": "Metallic Green", "tampo": "Gold accents, \"66\" on sides, silver exhaust pipes, Triumph logo on rider''s back, Treasure Hunt logo on seat cowl", "wheel": "MCCR", "toy": "JBC32", "notes": "Treasure Hunt / Base code(s):", "image": "https://static.wikia.nocookie.net/hotwheels/images/9/9b/TriumphRaceBike.jpg/revision/latest/scale-to-width-down/300?cb=20250715130457"}, "realCar": {"title": "Triumph Tiger 100", "url": "https://en.wikipedia.org/wiki/Triumph_Tiger_100", "description": "British motorcycle", "summary": "The Tiger 100 (T100) was a standard motorcycle first made by the British motorcycle company Triumph in 1939. Production ceased when the Triumph factory was destroyed by German bombing in 1940 during World War 2, but recommenced in 1946. Several variants were manufactured until 1973."}}');
INSERT INTO car_info (car_id, status, data) VALUES (7, 'confirmed', '{"casting": {"source": "Hot Wheels Wiki", "title": "Pagani Utopia", "url": "https://hotwheels.fandom.com/wiki/Pagani_Utopia", "fields": {"Debut series": "HW Exotics", "Produced": "2024 – Present", "Designer": "Ronald Wong", "Number": "HRY83"}}, "version": {"year": "2025", "series": "Peak Pursuit / 4/10", "color": "Metalflake Blu Francia", "tampo": "Detailed headlights and trim, \"Horacio Pagani\" signature on sides, \"Utopia\" on rear", "wheel": "Gold 10SP", "toy": "JBB38", "notes": "Base code(s): U22N, U24N, U25N", "image": "https://static.wikia.nocookie.net/hotwheels/images/3/35/2025PaganiUtopia.jpg/revision/latest/scale-to-width-down/300?cb=20250619120436"}, "realCar": {"title": "Pagani Utopia", "url": "https://en.wikipedia.org/wiki/Pagani_Utopia", "description": "Motor vehicle", "summary": "The Pagani Utopia is a mid-engine sports car produced by the Italian manufacturer Pagani. It was developed under the ''C10'' codename and presented on 12 September 2022 at the Teatro Lirico in Milan. It is Pagani''s third car model, superseding the Pagani Huayra, with more power and a manual gearbox option. The internal model code is C10; succeeding the C8 (Zonda) and C9 (Huayra). A roadster version the Utopia Roadster was introduced on 30 July 2024 with production limited to 130 units. "}}');
INSERT INTO car_info (car_id, status, data) VALUES (8, 'confirmed', '{"casting": {"source": "Hot Wheels Wiki", "title": "Lamborghini Huracán Sterrato", "url": "https://hotwheels.fandom.com/wiki/Lamborghini_Hurac%C3%A1n_Sterrato", "fields": {"Debut series": "HW Dirt", "Produced": "2024 – Present", "Designer": "Shawn Moghadam", "Number": "HRY87"}}, "version": {"year": "2025", "series": "Safari Mode / 1/5", "color": "Giallo Inti", "tampo": "Detailed headlights and trim, black & green stripes, white highlights, \"63\", \"Sterrato\" wordmark and Hot Wheels logo on doors", "wheel": "Black TRAP5", "toy": "JBB86", "notes": "Base code(s): U26N, U28N, U30N, U37N", "image": "https://static.wikia.nocookie.net/hotwheels/images/d/d2/Sterrato_yellow_%28front%29.png/revision/latest/scale-to-width-down/300?cb=20260106202528"}, "realCar": {"title": "Lamborghini Huracán", "url": "https://en.wikipedia.org/wiki/Lamborghini_Hurac%C3%A1n", "description": "Sports car manufactured by Lamborghini", "summary": "The Lamborghini Huracán (Spanish for \"hurricane\"; [uɾaˈkan]) is a mid-engine, two-seater sports car made by Lamborghini from 2014 to 2024. Revealed online in December 2013, the Huracán made its worldwide debut at the 2014 Geneva Auto Show and was released to the market in the second quarter of 2014, replacing the Gallardo. The Huracán was succeeded by the Temerario, announced in 2024. "}}');
INSERT INTO car_info (car_id, status, data) VALUES (9, 'confirmed', '{"casting": {"source": "Hot Wheels Wiki", "title": "''67 Ford Bronco", "url": "https://hotwheels.fandom.com/wiki/''67_Ford_Bronco", "fields": {"Debut series": "Hot Wheels Garage: Ford", "Produced": "2011 – Present", "Designer": "Brendon Vetuskey", "Number": "T8320"}}, "version": {"year": "2026", "series": "Pantone / 6/6", "color": "Earthbound Embrace", "tampo": "Detailed headlights, taillights and trim, white, gray and black striping, \"PANTONE 175\" on sides", "wheel": "White lip, Earthbound Embrace BAJA5", "toy": "JKY65", "notes": "Base code(s): V07A, V09A, V12A", "image": "https://static.wikia.nocookie.net/hotwheels/images/5/59/JKY65.jpg/revision/latest/scale-to-width-down/300?cb=20260619102449"}, "realCar": null}');
INSERT INTO car_info (car_id, status, data) VALUES (10, 'confirmed', '{"casting": {"source": "Hot Wheels Wiki", "title": "Nissan Fairlady Z", "url": "https://hotwheels.fandom.com/wiki/Nissan_Fairlady_Z", "fields": {"Debut series": "HW Speed Graphics", "Produced": "2016 - Present", "Designer": "Jun Imai", "Number": "DHP27"}}, "version": {"year": "2026", "series": "Pantone Multipack", "color": "Vibrant Blue", "tampo": "Detailed headlights, taillights and trim, \"PANTONE 533\" on sides", "wheel": "White lip, Vibrant Blue S5", "toy": "JNN67", "notes": "Base code(s): U49A, U50A", "image": "https://static.wikia.nocookie.net/hotwheels/images/1/1a/NissanFairladyPantone.png/revision/latest/scale-to-width-down/300?cb=20260204193328"}, "realCar": {"title": "Nissan Fairlady Z (S130)", "url": "https://en.wikipedia.org/wiki/Nissan_Fairlady_Z_(S130)", "description": "Motor vehicle", "summary": "The Nissan S130 is a sports coupé produced by Nissan in Japan from 1978 until 1983. It was sold as the Datsun 280ZX, Nissan Fairlady Z and Nissan Fairlady 280Z, depending on the market. In Japan, it was exclusive to Nissan Bluebird Store locations. It was the second generation Z-car, replacing the Nissan Fairlady Z (S30) in late 1978. The 280ZX was the first time the \"by Nissan\" subscript was badged alongside the Datsun logo, along with Nissan trucks. The 280ZX was Motor Trend''s import car of the year for 1979. The 280ZX was replaced by the Nissan 300ZX in 1984. "}}');
INSERT INTO car_info (car_id, status, data) VALUES (11, 'confirmed', '{"casting": {"source": "Hot Wheels Wiki", "title": "''20 Toyota Tacoma", "url": "https://hotwheels.fandom.com/wiki/''20_Toyota_Tacoma", "fields": {"Debut series": "HW Hot Trucks", "Produced": "2022 – Present", "Designer": "Ryu Asada", "Number": "HCT18"}}, "version": {"year": "2026", "series": "Pantone / 1/6", "color": "Earthy Forest Gloom", "tampo": "Detailed headlights, taillights and trim, \"PANTONE 574\" on sides", "wheel": "White lip, Earthy Forest Gloom BAJA5", "toy": "JKY57", "notes": "Base code(s): V09A, V12A", "image": "https://static.wikia.nocookie.net/hotwheels/images/b/ba/JKY57.jpg/revision/latest/scale-to-width-down/300?cb=20260619084337"}, "realCar": {"title": "Toyota Tacoma", "url": "https://en.wikipedia.org/wiki/Toyota_Tacoma", "description": "Mid-size pickup truck", "summary": "The Toyota Tacoma is a pickup truck manufactured by Japanese automobile manufacturer Toyota since 1995. The first-generation Tacoma (model years 1995 through 2004) was classified as a compact pickup truck; subsequent models are classified as mid-size pickup trucks. The Tacoma was Motor Trend''s Truck of the Year for 2005. As of 2015, the Tacoma was sold in the United States, Canada, Mexico, Costa Rica, Bolivia, Bermuda, and the French overseas collectivity of New Caledonia. Most markets across the world receive the Toyota Hilux in lieu of the Tacoma."}}');
INSERT INTO car_info (car_id, status, data) VALUES (12, 'confirmed', '{"casting": {"source": "Hot Wheels Wiki", "title": "DMC DeLorean", "url": "https://hotwheels.fandom.com/wiki/DMC_DeLorean", "fields": {"Debut series": "2010 New Models", "Produced": "2010 - 2014 (original) / 2015 - Present (retool)", "Designer": "Manson Cheung", "Number": "R0931"}}, "version": {"year": "2023", "series": "HW: The ''80s / 8/10", "color": "Metalflake Pale Blue", "tampo": "Blue, Light Blue, and Black stripes on hood and sides. \"DELOREAN\" on hood, HW logo on sides", "wheel": "Gold 10SP", "toy": "HKG84", "notes": "Base code(s): R46, R47, R49, R50, R52", "image": "https://static.wikia.nocookie.net/hotwheels/images/c/cc/HKG84-LOOSE.jpg/revision/latest/scale-to-width-down/300?cb=20230219095234"}, "realCar": {"title": "DMC DeLorean", "url": "https://en.wikipedia.org/wiki/DMC_DeLorean", "description": "1980s automobile", "summary": "The DMC DeLorean is a rear-engine, two-seat sports car manufactured and marketed by John DeLorean''s DeLorean Motor Company (DMC) for the American market from 1981 until 1983—ultimately the only car brought to market by the fledgling company. The DeLorean is sometimes referred to by its internal pre-production designation, DMC-12, although this was not used in sales or marketing materials for the production model. Designed by Giorgetto Giugiaro, the DeLorean is noted for its gull-wing doors and brushed stainless-steel outer body panels, as well as its relatively modest performance."}}');
INSERT INTO car_info (car_id, status, data) VALUES (13, 'confirmed', '{"casting": {"source": "Hot Wheels Wiki", "title": "Back to the Future - 1955", "url": "https://hotwheels.fandom.com/wiki/Back_to_the_Future_-_1955", "fields": {"Debut series": "Hot Wheels Entertainment: Back to the Future Part III", "Produced": "2015 - Present", "Designer": "Manson Cheung", "Number": "CFR30"}}, "version": {"year": "2022", "series": "Replica Entertainment: Back to the Future Part III", "color": "Unpainted", "tampo": "Black stripes on sides, detailed grille, hood, Mr. Fusion, & license plate", "wheel": "Brown BTTFRW", "toy": "HCP22", "notes": "Base code(s): R04", "image": "https://static.wikia.nocookie.net/hotwheels/images/3/3a/Entertainment_Back_to_the_Future_Time_Machine_-_1955_HCP22_2022.jpg/revision/latest/scale-to-width-down/300?cb=20220407175500"}, "realCar": {"title": "DeLorean time machine", "url": "https://en.wikipedia.org/wiki/DeLorean_time_machine", "description": "Back to the Future time travel vehicle", "summary": "In the Back to the Future franchise, the DeLorean time machine is a time travel vehicle constructed from a retrofitted DMC DeLorean. Its time travel ability is derived from the \"flux capacitor\", a component that allows the car to travel to the past or future. This occurs when the car accelerates to 88 miles per hour and requires 1.21 gigawatts of electricity. In 2021, the time machine was added to the Library of Congress''s National Historic Vehicle Register. "}}');
INSERT INTO car_info (car_id, status, data) VALUES (17, 'confirmed', '{"casting": {"source": "Matchbox Wiki", "title": "2024 Subaru WRX S4 STI", "url": "https://matchbox.fandom.com/wiki/2024_Subaru_WRX_S4_STI", "fields": {}}, "version": {"year": "2026", "series": "1-125: MBX Metro", "color": "Ignition Red", "tampo": "Detailed trim front & rear, \"3U L1T5R\" rear plate", "wheel": "", "toy": "JHM46 (USA) / JHR16 (PG)", "notes": "Packaging Code(s): V14A, V17A, V21A", "image": "https://static.wikia.nocookie.net/matchbox/images/5/5b/WRXred1.png/revision/latest/scale-to-width-down/300?cb=20260806195403"}, "realCar": {"title": "Subaru WRX STI", "url": "https://en.wikipedia.org/wiki/Subaru_WRX_STI", "description": "Compact sports car", "summary": "The Subaru WRX STI is a variant of the Subaru WRX sedan produced by in-house tuning company Subaru Tecnica International between 2014 and 2021. It succeeded the Subaru Impreza WRX STI. Production of the WRX STI concluded after its first generation, there are currently no plans for a VB WRX STI."}}');
